{"component": {"id": 19366, "componentId": 9943, "authorUserId": "user_registry_corr_1783515809347", "name": "Notice Alert", "demoName": "Default", "description": "A restrained alert wrapper with info, success, warning, primary, and destructive tones for inline notices and status messages.", "previewUrl": "https://cdn.21st.dev/corr/notice-alert/default/preview.1784723104620-22d682d0-eefc-4af7-8ae9-1855c45c3304.png", "installCommand": "npx shadcn@latest add "https://21st.dev/r/corr/notice-alert?api_key=$API_KEY_21ST"", "componentCode": "import { AlertCircle, CheckCircle2, Info, TriangleAlert } from "lucide-react";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { cn } from "@/lib/utils";

export type NoticeAlertTone =
  "primary" | "info" | "success" | "warning" | "destructive";

export function NoticeAlert({
  title,
  description,
  tone = "info",
  className,
}: {
  title: string;
  description?: string;
  tone?: NoticeAlertTone;
  className?: string;
}) {
  const Icon =
    tone === "success"
      ? CheckCircle2
      : tone === "warning"
        ? TriangleAlert
        : tone === "destructive"
          ? AlertCircle
          : Info;

  return (
    <Alert
      variant={tone === "destructive" ? "destructive" : "default"}
      className={cn(
        "items-start gap-3 rounded-md border bg-background py-2.5 pb-2 shadow-none",
        tone === "primary" &&
          "border-primary/25 bg-primary/10 text-primary dark:bg-primary/15",
        tone === "success" &&
          "border-emerald-500/25 bg-emerald-500/10 text-emerald-950 dark:border-emerald-400/30 dark:bg-emerald-500/15 dark:text-emerald-100",
        tone === "warning" &&
          "border-amber-500/25 bg-amber-500/10 text-amber-950 dark:border-amber-400/30 dark:bg-amber-500/15 dark:text-amber-100",
        tone === "info" &&
          "border-blue-500/25 bg-blue-500/10 text-blue-950 dark:border-blue-400/30 dark:bg-blue-500/15 dark:text-blue-100",
        tone === "destructive" &&
          "border-destructive/35 bg-destructive/10 text-destructive dark:bg-destructive/15",
        className,
      )}
    >
      <Icon className="size-4" />
      <div className="min-w-0">
        <AlertTitle>{title}</AlertTitle>
        {description ? (
          <AlertDescription>{description}</AlertDescription>
        ) : null}
      </div>
    </Alert>
  );
}

export default NoticeAlert;
